param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'derived-exception-serialization-collisions-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture


function Text($units){if($null -eq $units){return $null};return [string]::new([char[]]([int[]]$units))}
function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new();$index=0;$nullInputControls=0
foreach($profile in $plan.profiles){$native=switch($profile){'Exception'{[Exception]};'ArgumentException'{[ArgumentException]};'ArgumentNullException'{[ArgumentNullException]};'ArgumentOutOfRangeException'{[ArgumentOutOfRangeException]};'CultureNotFoundException'{[Globalization.CultureNotFoundException]};'FileNotFoundException'{[IO.FileNotFoundException]};'FileLoadException'{[IO.FileLoadException]};'TypeLoadException'{[TypeLoadException]}};foreach($m in 0..2){foreach($f in 0..2){foreach($collision in $plan.collisions){foreach($flag in $plan.contextFlags){foreach($observe in $plan.observeMessage){$message=Text $plan.texts[$m];$param=Text $plan.texts[$f];$messageSlot=0;$paramSlot=-1
switch($profile){'ArgumentOutOfRangeException'{$types=[type[]]@([string],[object],[string]);$arguments=[object[]]::new(3);$arguments[0]=$param;$arguments[1]=[int]42;$arguments[2]=$message;$messageSlot=2;$paramSlot=0};'CultureNotFoundException'{$types=[type[]]@([string],[int],[string]);$arguments=[object[]]::new(3);$arguments[0]=$param;$arguments[1]=[int]1033;$arguments[2]=$message;$messageSlot=2;$paramSlot=0};'ArgumentNullException'{$types=[type[]]@([string],[string]);$arguments=[object[]]::new(2);$arguments[0]=$param;$arguments[1]=$message;$messageSlot=1;$paramSlot=0};{$_ -in @('ArgumentException','FileNotFoundException','FileLoadException')}{$types=[type[]]@([string],[string]);$arguments=[object[]]::new(2);$arguments[0]=$message;$arguments[1]=$param;$paramSlot=1};default{$types=[type[]]@([string]);$arguments=[object[]]::new(1);$arguments[0]=$message}}
if($m -eq 0){if($null -ne $arguments[$messageSlot]){throw 'Null message coerced'};$nullInputControls++};if($f -eq 0 -and $paramSlot -ge 0){if($null -ne $arguments[$paramSlot]){throw 'Null parameter coerced'};$nullInputControls++};$e=$native.GetConstructor($types).Invoke($arguments);if($observe){$null=$e.Message};$info=[Runtime.Serialization.SerializationInfo]::new($native,[Runtime.Serialization.FormatterConverter]::new());$info.AddValue($collision,[object]'preseed',[string]);$context=[Runtime.Serialization.StreamingContext]::new([Runtime.Serialization.StreamingContextStates]$flag);$errorName='none';$errorMessage=$null;$errorHResult=0;try{$e.GetObjectData($info,$context)}catch{$errorValue=$_.Exception;while($null -ne $errorValue.InnerException){$errorValue=$errorValue.InnerException};if($errorValue -isnot [Runtime.Serialization.SerializationException]){throw};$errorName=$errorValue.GetType().FullName;$errorMessage=$errorValue.Message;$errorHResult=$errorValue.HResult};$entries=[Collections.Generic.List[object]]::new();$it=$info.GetEnumerator();while($it.MoveNext()){$entry=$it.Current;$value=$entry.Value;$kind='null';$units=$null;$number=$null;if($null -ne $value){if($value -is [string]){$kind='text';$units=Units $value}elseif($value -is [int]){$kind='int';$number=[int]$value}else{throw 'Unexpected native value carrier'}};$entries.Add([ordered]@{name=$entry.Name;type=$entry.ObjectType.FullName;kind=$kind;units=$units;number=$number})};$rows.Add([ordered]@{index=$index;profile=$profile;messageIndex=$m;paramIndex=$f;collision=$collision;contextFlag=$flag;observeMessage=[bool]$observe;memberCount=$info.MemberCount;exception=$errorName;errorMessageUnits=(Units $errorMessage);errorHResult=$errorHResult;entries=$entries.ToArray()});$index++}}}}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();nullInputControls=$nullInputControls;rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 20 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS derived collisions: $($rows.Count) attempts"
